// Room "P7 north-west bedroom" (interior designer's part): box x116..119, y6..8, z14..17. Door in the east wall at
// (120,6..7,16); window pair in the north wall above x116. Two beds with heads on solid walls: the red bed's head on the
// north wall (x117, z14), the blue bed's head on the south partition (x118, z17). The barrel nightstand between them
// (x118, z14) carries a standing lantern, the chest under the window (x116, z14) a potted poppy. Rug on the floor at
// x117 z16..17. Column x116 z15..17 and x119 stay clear: the stair at x115 opens into the room's west side, and the door
// lane runs along x119.
import { bed, layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // the beds: foot, then the head one step toward facing (the pillow end against the wall)
  bed(g, [117, 6, 15], "north", "red");
  bed(g, [118, 6, 16], "south", "blue");

  // y6 floor layer, rows along +z from z14 (north) to z17, columns x116..119
  // C chest (facing into the room), B barrel nightstand, R brown carpet rug; beds are placed by bed() above
  // y7 layer: P potted poppy on the chest, L lantern standing on the barrel (the room's light)
  layers(g, [116, 6, 14], {
    "C": ["chest", { facing: "south" }],
    "B": "barrel",
    "R": "brown_carpet",
    "P": "potted_poppy",
    "L": ["lantern", { hanging: "false" }],
  }, [
    [
      "C B ",   // z14: chest under the window, barrel nightstand, gap left for the bed head
      "    ",   // z15: lane (x116 stair side, x118 between the beds)
      " R  ",   // z16: rug in front of the red bed's foot
      " R  ",   // z17: rug, lane east
    ],
    [
      "P L ",   // z14: pot on the chest, lantern on the barrel
      "    ",
      "    ",
      "    ",
    ],
  ]);
}

